() => {
  // Get the title of the current page and any visible info panels
  const title = document.title;
  const headings = Array.from(document.querySelectorAll('h1, h2, h3')).map(h => h.textContent.trim());
  const infoPanel = document.querySelector('[role="main"]')?.textContent?.slice(0, 2000);
  return {
    title,
    headings,
    url: window.location.href,
    infoPanel
  };
}

() => {
  // Close any open dropdowns or overlays
  document.activeElement?.blur();
  document.querySelector('[role="dialog"]')?.remove();
  return document.body.innerText.substring(0, 200);
}

() => {
  // Try to close the search suggestions
  const evt = new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true });
  document.dispatchEvent(evt);
  document.activeElement?.blur();
  // Click somewhere else
  return 'attempted to close';
}

() => {
  // Find all close buttons
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"]');
  const result = [];
  closeButtons.forEach((btn, i) => {
    result.push({
      index: i,
      visible: btn.offsetParent !== null,
      rect: btn.getBoundingClientRect().toJSON()
    });
  });
  // Click all visible close buttons
  closeButtons.forEach(btn => {
    if (btn.offsetParent !== null) btn.click();
  });
  return result;
}

() => {
  // Try to invoke the print function and capture any errors
  try {
    window.print();
    return 'Print dialog invoked';
  } catch(e) {
    return 'Print error: ' + e.message;
  }
}
